function Shop({ onBuy, purchasedItems }) {
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);

  // Decode token
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = jwtDecode(token);
        setCurrentUserId(decoded.id || decoded.userId || decoded._id); // be flexible
      } catch (err) {
        console.error("Invalid token:", err);
      }
    }
  }, []);

  // Fetch books
  useEffect(() => {
    setLoading(true);
    fetch("http://localhost:5009/books")
      .then((res) => res.json())
      .then((data) => {
        setItems(data);
      })
      .catch((err) => console.error("Error fetching books:", err))
      .finally(() => setLoading(false));
  }, []);

  // Filter only when we have both data and userId
  const filteredItems = items.filter((item) => {
    if (!currentUserId) return true;           // show all until we know who the user is
    return String(item.userId) !== String(currentUserId); // safe string comparison
  });

  if (loading) {
    return (
      <>
        <Navbar />
        <div className="Body">
          <div className="HeadMoe">
            <div className="HeadMo">
              <h1>Loading books...</h1>
            </div>
          </div>
        </div>
        <Footer />
      </>
    );
  }

  return (
    <>
      <Navbar />
      <div className="Body">
        {filteredItems.length === 0 ? (
          <div className="HeadMoe">
            <div className="HeadMo">
              <h1>No books!</h1>
            </div>
          </div>
        ) : (
          filteredItems.map((item) => (
            <Card
              key={item.id}
              pic={item.pic}
              title={item.title}
              para={item.para}
              price={item.price}
            >
              <button
                onClick={() => onBuy(item)}
                disabled={!!purchasedItems[item.id]}
                style={{
                  backgroundColor: purchasedItems[item.id]
                    ? "grey"
                    : "rgba(13, 110, 264, 1)",
                  color: "#fff",
                  borderRadius: "5px",
                  padding: "5px",
                  fontWeight: "100",
                  fontFamily: "Century Gothic",
                  width: "130px",
                }}
              >
                {purchasedItems[item.id] ? "Sold" : "Add to Cart"}
              </button>
            </Card>
          ))
        )}
      </div>
      <Footer />
    </>
  );
}

export default Shop;
